// Append one bit (value 0/1) at bit position pos of buf (LSB-first inside each byte).
static void putbit(u8 *buf, int pos, int bit) { if (bit) buf[pos >> 3] |= (u8)(1 << (pos & 7)); }
// Sponge: message bits, domain suffix bits, then pad10*1 up to a multiple of the rate; absorb; squeeze outlen bytes.
static void sponge(int rate_bytes, const u8 *msg, int nbits, int xof, u8 *out, int outlen) {
    static u8 buf[1024]; u64 a[25];
    int pos = nbits, rate_bits = rate_bytes * 8;
    for (int i = 0; i < 1024; i++) buf[i] = 0;
    for (int i = 0; i < nbits; i++) putbit(buf, i, (msg[i >> 3] >> (i & 7)) & 1);
    if (xof) { for (int i = 0; i < 4; i++) putbit(buf, pos++, 1); }
    else { putbit(buf, pos++, 0); putbit(buf, pos++, SHA3_SUFFIX_BAD ? 0 : 1); }
    putbit(buf, pos++, 1);                                   /* pad10*1: first 1 */
    while (pos % rate_bits != rate_bits - 1) pos++;           /* zeros */
    putbit(buf, pos++, 1);                                   /* last 1 */
    for (int i = 0; i < 25; i++) a[i] = 0;
    for (int off = 0; off < pos / 8; off += rate_bytes) {
        for (int i = 0; i < rate_bytes; i++) a[i / 8] ^= (u64)buf[off + i] << (8 * (i % 8));
        keccak_f(a);
    }
    int o = 0;
    while (1) {
        for (int i = 0; i < rate_bytes && o < outlen; i++) out[o++] = (u8)(a[i / 8] >> (8 * (i % 8)));
        if (o >= outlen) break;
        keccak_f(a);
    }
}
