static int run(const char *name, int rate_bytes, int outlen, int xof, const struct kat *k, int n) {
    int good = 0;
    static u8 msg[260], got[512], want[512];
    for (int i = 0; i < n; i++) {
        int mb = (k[i].bits + 7) / 8; if (k[i].bits == 0) mb = 1;
        for (int j = 0; j < mb; j++) msg[j] = (u8)(hexval(k[i].msg[2 * j]) * 16 + hexval(k[i].msg[2 * j + 1]));
        for (int j = 0; j < outlen; j++) want[j] = (u8)(hexval(k[i].out[2 * j]) * 16 + hexval(k[i].out[2 * j + 1]));
        sponge(rate_bytes, msg, k[i].bits, xof, got, outlen);
        int ok = 1; for (int j = 0; j < outlen; j++) if (got[j] != want[j]) ok = 0;
        good += ok;
        if (!ok) { pstr("FAIL "); pstr(name); pstr(" bit length "); pdec(k[i].bits); pstr("\n"); }
    }
    pstr(name); pstr(": "); pdec(good); pstr(" of "); pdec(n); pstr(" match\n");
    return good;
}
int paper_main(void) {
    int good = 0;
    good += run("SHA3-224", 144, 28, 0, K_SHA3224, 46);
    good += run("SHA3-256", 136, 32, 0, K_SHA3256, 46);
    good += run("SHA3-384", 104, 48, 0, K_SHA3384, 51);
    good += run("SHA3-512", 72, 64, 0, K_SHA3512, 56);
    good += run("SHAKE128", 168, 512, 1, K_SHAKE128, 46);
    good += run("SHAKE256", 136, 512, 1, K_SHAKE256, 46);
    pstr("total: "); pdec(good); pstr(" of 291 match\n");
    pstr(good == 291 ? "PASS\n" : "FAIL\n");
    return good == 291 ? 0 : 1;
}
